import{_ as a,o as t,c as n,O as r}from"./app.66db9b54.js";const l='{"title":"About","description":"","frontmatter":{},"headers":[{"level":3,"title":"Composition API","slug":"composition-api"},{"level":3,"title":"Two-way data binding","slug":"two-way-data-binding"},{"level":3,"title":"Support Vue2 and Vue3","slug":"support-vue2-and-vue3"},{"level":3,"title":"Extensions and tests","slug":"extensions-and-tests"}],"relativePath":"en/guide/index.md"}',o={};function d(s,e,i,p,h,u){return t(),n("div",null,e[0]||(e[0]=[r('<p><a href="https://www.npmjs.com/package/react-dnd-html5-backend" target="_blank" rel="noopener noreferrer">react-dnd-html5-backend</a> is a [React DnD](<a href="https://react-dnd.github.io/react" target="_blank" rel="noopener noreferrer">https://react-dnd.github.io/react</a> -dnd/about) plugin which provides an HTML5 drag and drop support; you can also use [react-dnd-touch-backend](<a href="https://www.npmjs.com/package/react-dnd-touch-" target="_blank" rel="noopener noreferrer">https://www.npmjs.com/package/react-dnd-touch-</a> backend) provides touch drag and drop support.</p><h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-hidden="true">#</a></h1><h3 id="composition-api" tabindex="-1">Composition API <a class="header-anchor" href="#composition-api" aria-hidden="true">#</a></h3><p>Based on Vue&#39;s composition API, you can use drag and drop in any component.</p><h3 id="two-way-data-binding" tabindex="-1">Two-way data binding <a class="header-anchor" href="#two-way-data-binding" aria-hidden="true">#</a></h3><p>Based on Vue&#39;s two-way data binding, you can automatically update the UI when the data is updated.</p><h3 id="support-vue2-and-vue3" tabindex="-1">Support Vue2 and Vue3 <a class="header-anchor" href="#support-vue2-and-vue3" aria-hidden="true">#</a></h3><p>Support both Vue2 and Vue3 versions</p><h3 id="extensions-and-tests" tabindex="-1">Extensions and tests <a class="header-anchor" href="#extensions-and-tests" aria-hidden="true">#</a></h3><p>Benefiting from React DnD&#39;s backend design, you can customize a DnD backend and test it with <a href="https://www.npmjs.com/package/react-dnd-test-backend" target="_blank" rel="noopener noreferrer">react-dnd-test-backend</a> Your drag and drop component.</p><h1 id="questions-and-suggestions" tabindex="-1">Questions and suggestions <a class="header-anchor" href="#questions-and-suggestions" aria-hidden="true">#</a></h1><p>You can submit an issue or pull request on <a href="https://github.com/hcg1023/vue3-dnd" target="_blank" rel="noopener noreferrer">GitHub</a>.</p><h1 id="thanks" tabindex="-1">Thanks <a class="header-anchor" href="#thanks" aria-hidden="true">#</a></h1><p>Thanks to the authors of <a href="https://react-dnd.github.io/react-dnd/about" target="_blank" rel="noopener noreferrer">React DnD</a> whose open source project is our foundation.</p><p>Thanks to designer Wang Heng for the logo.</p>',15)]))}var g=a(o,[["render",d]]);export{l as __pageData,g as default};
